function IsPalindrome(s: string): boolean;
begin
  Result := s = s.Inverse;
end;

procedure DFS(s: string; start: integer; path: List<string>; var res: List<List<string>>);
begin
  if start = s.Length then
  begin
    res.Add(new List<string>(path));
    exit;
  end;

  for var endIndex := start to s.Length - 1 do
  begin
    var substr := s.Substring(start, endIndex - start + 1);
    if IsPalindrome(substr) then
    begin
      path.Add(substr);
      DFS(s, endIndex + 1, path, res);
      path.RemoveAt(path.Count - 1);
    end;
  end;
end;

