function BalancedParentheses(n: integer): integer;
begin
  if n = 1 then
    Result := 1
  else
  begin
    var dp := ArrFill(n + 1, 0);
    dp[0] := 1;
    dp[1] := 1;
    for var i := 2 to n do
      for var j := 0 to i - 1 do
        dp[i] := dp[i] + dp[j] * dp[i - j - 1];
    Result := dp[n];
  end;
end;

