function MaxLengthOfSubarray(arr: List<integer>): integer;
begin
  var n := arr.Count;
  var maxLen := 0;
  var left := 0;
  var right := 0;
  var zeroCount := 0;

  while right < n do
  begin
    if arr[right] = 0 then
      zeroCount += 1;

    while zeroCount > 1 do
    begin
      if arr[left] = 0 then
        zeroCount -= 1;
      left += 1;
    end;

