  dp[0] := 0;

  foreach var coin in coins do
    for var x := coin to amount do
      if dp[x - coin] <> integer.MaxValue then
        dp[x] := Min(dp[x], dp[x - coin] + 1);

  if dp[amount] = integer.MaxValue then
    Result := -1
  else
    Result := dp[amount];
end;

