function _Match(s, pattern: string; i, j: integer; var memo: Dictionary<(integer, integer), boolean>): boolean;
begin
  if memo.ContainsKey((i, j)) then
    Result := memo[(i, j)]
  else
  begin
    if j = pattern.Length then
      Result := i = s.Length
    else if (i < s.Length) and ((pattern[j] = '?') or (pattern[j] = s[i])) then
      Result := _Match(s, pattern, i + 1, j + 1, memo)
    else if (j + 1 < pattern.Length) and (pattern[j + 1] = '*') then
      Result := _Match(s, pattern, i, j + 2, memo) or ((i < s.Length) and _Match(s, pattern, i + 1, j, memo))
    else
      Result := False;

    memo[(i, j)] := Result;
  end;
end;

function PatternMatching(s, pattern: string): boolean;
begin
  var memo := new Dictionary<(integer, integer), boolean>;
  Result := _Match(s, pattern, 0, 0, memo);
end;

