function MinUniqueSet(arr: List<integer>): integer;
begin
  var counts := new Dictionary<integer, integer>;

  foreach var num in arr do
    if counts.ContainsKey(num) then
      counts[num] := counts[num] + 1
    else
      counts.Add(num, 1);

  var sortedKeys := counts.Keys.OrderByDescending(key -> counts[key]).ToList;
  var n := arr.Count;
  var cnt := 0;
  var ans := 0;

  foreach var key in sortedKeys do
  begin
    cnt := cnt + counts[key];
    ans := ans + 1;
    if cnt >= (n + 1) div 2 then
    begin
      Result := ans;
      exit;
    end;
  end;

  Result := ans;
end;

