function Merge(var arr: array of integer; var tempArr: array of integer; left, mid, right: integer): integer;
begin
  var i := left;
  var j := mid + 1;
  var k := left;
  var invCount := 0;

  while (i <= mid) and (j <= right) do
  begin
    if arr[i] <= arr[j] then
    begin
      tempArr[k] := arr[i];
      k += 1;
      i += 1;
    end
    else
    begin
      tempArr[k] := arr[j];
      invCount := invCount + (mid - i + 1);
      k += 1;
      j += 1;
    end;
  end;

  while i <= mid do
  begin
    tempArr[k] := arr[i];
    k += 1;
    i += 1;
  end;

  while j <= right do
  begin
    tempArr[k] := arr[j];
    k += 1;
    j += 1;
  end;

  for var loopVar := left to right do
    arr[loopVar] := tempArr[loopVar];

  Result := invCount;
end;

function MergeSortHelper(var arr: array of integer; var tempArr: array of integer; left, right: integer): integer;
begin
  var invCount := 0;
  if left < right then
  begin
    var mid := (left + right) div 2;
    invCount := invCount + MergeSortHelper(arr, tempArr, left, mid);
    invCount := invCount + MergeSortHelper(arr, tempArr, mid + 1, right);
    invCount := invCount + Merge(arr, tempArr, left, mid, right);
  end;
  Result := invCount;
end;

function MergeSort(arr: array of integer; n: integer): integer;
begin
  var tempArr := new integer[n];
  Result := MergeSortHelper(arr, tempArr, 0, n - 1);
end;

function FindInversions(arr: array of integer): integer;
