function MaxSubarraySum(arr: List<integer>; k: integer): integer;
begin
  if arr.Count = 0 then
    Result := 0
  else
  begin
    var maxSum := 0;
    var currentSum := 0;

    for var i := 0 to k - 1 do
      currentSum := currentSum + arr[i];

    maxSum := currentSum;

    for var i := k to arr.Count - 1 do
    begin
      currentSum := currentSum + arr[i] - arr[i - k];
