procedure DFS(k, target, start: integer; path: List<integer>; var res: List<List<integer>>);
begin
  if path.Count = k then
  begin
    if target = 0 then
      res.Add(new List<integer>(path));
    exit;
  end;

  for var i := start to 9 do
  begin
    if i > target then break;
    path.Add(i);
    DFS(k, target - i, i + 1, path, res);
    path.RemoveAt(path.Count - 1);
  end;
end;

