function FindNumTriangles(segments: List<integer>): integer;
begin
  segments.Sort;
  var count := 0;
  var n := segments.Count;

  for var i := 0 to n - 2 do
  begin
    var k := i + 2;
    for var j := i + 1 to n - 1 do
    begin
      while (k < n) and (segments[i] + segments[j] > segments[k]) do
        k := k + 1;
      count := count + k - j - 1;
    end;
  end;

  Result := count;
end;

function HasCycle(graph: Dictionary<integer, List<integer>>; visited: array of boolean; parent, node: integer): boolean;
begin
  visited[node] := True;

  if graph.ContainsKey(node) then
    foreach var neighbor in graph[node] do
    begin
      if not visited[neighbor] then
      begin
        if HasCycle(graph, visited, node, neighbor) then
        begin
          Result := True;
          exit;
        end;
      end
      else if neighbor <> parent then
      begin
        Result := True;
        exit;
      end;
    end;

  Result := False;
end;

function IsTree(numNodes: integer; edges: List<List<integer>>): boolean;
begin
  var graph := new Dictionary<integer, List<integer>>;

  foreach var edge in edges do
  begin
    var u := edge[0];
    var v := edge[1];

    if not graph.ContainsKey(u) then
      graph.Add(u, new List<integer>);
    if not graph.ContainsKey(v) then
      graph.Add(v, new List<integer>);

    graph[u].Add(v);
    graph[v].Add(u);
  end;

  var visited := ArrFill(numNodes, False);

  if HasCycle(graph, visited, -1, 0) then
    Result := False
  else
  begin
    foreach var v in visited do
      if not v then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

