function MaxArea(height: List<integer>): integer;
begin
  var left := 0;
  var right := height.Count - 1;
  var maxArea := 0;

  while left < right do
  begin
    maxArea := Max(maxArea, Min(height[left], height[right]) * (right - left));
    if height[left] < height[right] then
      left := left + 1
    else
      right := right - 1;
  end;

