function GeneratePermutations(s: string): List<string>;
begin
  s := s.Replace(#10, '');
  var length := s.Length;

  if length = 1 then
  begin
    Result := new List<string>;
    Result.Add(s);
    exit;
  end;

  var results := new List<string>;
  for var i := 0 to length - 1 do
  begin
    var temp := s.Substring(0, i) + s.Substring(i + 1);
    var tempPerms := GeneratePermutations(temp);
    foreach var perm in tempPerms do
      results.Add(s[i] + perm);
  end;

  Result := results;
end;

function FindQuadruplets(nums: List<integer>; target: integer): List<List<integer>>;
begin
  nums.Sort;
  var results := new List<List<integer>>;
  var n := nums.Count;

  for var i := 0 to n - 3 do
  begin
    if (i > 0) and (nums[i] = nums[i - 1]) then continue;

    for var j := i + 1 to n - 2 do
    begin
      if (j > i + 1) and (nums[j] = nums[j - 1]) then continue;

      var left := j + 1;
      var right := n - 1;

      while left < right do
      begin
        var total := nums[i] + nums[j] + nums[left] + nums[right];
        if total = target then
        begin
          results.Add(new List<integer>(|nums[i], nums[j], nums[left], nums[right]|));
          while (left < right) and (nums[left] = nums[left + 1]) do
            left := left + 1;
          while (left < right) and (nums[right] = nums[right - 1]) do
            right := right - 1;
          left := left + 1;
          right := right - 1;
        end
        else if total < target then
          left := left + 1
        else
          right := right - 1;
      end;
    end;
  end;

  Result := results;
end;

