function FarthestPoint(points: List<(real, real)>): (real, real);
begin
  var farthest := points[0];
  var farthestDistance := Sqrt(farthest.Item1 * farthest.Item1 + farthest.Item2 * farthest.Item2);

  foreach var point in points do
  begin
    var distance := Sqrt(point.Item1 * point.Item1 + point.Item2 * point.Item2);
    if distance > farthestDistance then
    begin
      farthest := point;
      farthestDistance := distance;
    end;
  end;

  Result := farthest;
end;

function MinimumInterval(tasks: List<integer>; n: integer): integer;
begin
  var taskCounts := new Dictionary<integer, integer>;

  foreach var task in tasks do
    if taskCounts.ContainsKey(task) then
      taskCounts[task] := taskCounts[task] + 1
    else
      taskCounts.Add(task, 1);

  var maxCount := taskCounts.Values.Max;
  var maxTask := taskCounts.Count(kv -> kv.Value = maxCount);
  var partCount := maxCount - 1;
  var partLength := n - (maxTask - 1);
  var emptySlots := partCount * partLength;
  var availableTasks := tasks.Count - maxCount * maxTask;
  var idles := Max(0, emptySlots - availableTasks);

  Result := tasks.Count + idles;
end;

