function QuicksortRandomPivot(numbers: List<integer>): List<integer>;
begin
  if numbers.Count <= 1 then
    Result := numbers
  else
  begin
    var pivot := numbers[&System.Random.Create.Next(numbers.Count)];
    var less := new List<integer>;
    var equal := new List<integer>;
    var greater := new List<integer>;

    foreach var i in numbers do
      if i < pivot then
        less.Add(i)
      else if i = pivot then
        equal.Add(i)
      else
        greater.Add(i);

    Result := QuicksortRandomPivot(less).Concat(equal).Concat(QuicksortRandomPivot(greater)).ToList;
  end;
end;

