function FindMinHeightTrees(n: integer; edges: List<List<integer>>): List<integer>;
begin
  if n = 1 then
  begin
    Result := new List<integer>;
    Result.Add(0);
    exit;
  end;

  var d := new Dictionary<integer, HashSet<integer>>;

  foreach var edge in edges do
  begin
    var start := edge[0];
    var endVal := edge[1];

    if not d.ContainsKey(start) then
      d.Add(start, new HashSet<integer>);
    if not d.ContainsKey(endVal) then
      d.Add(endVal, new HashSet<integer>);

    d[start].Add(endVal);
    d[endVal].Add(start);
  end;

  var q := new List<integer>;
  foreach var kv in d do
    if kv.Value.Count = 1 then
      q.Add(kv.Key);

  while n > 2 do
  begin
    var t := new List<integer>;
    foreach var i in q do
    begin
      var j := d[i].First;
      d[j].Remove(i);
      if d[j].Count = 1 then
        t.Add(j);
      n := n - 1;
    end;
    q := t;
  end;

  Result := q;
end;

