function FindDiagonalOrder(mat: List<List<integer>>): List<integer>;
begin
  var sizeRow := mat.Count;
  var sizeCol := mat[0].Count;
  var res := new List<integer>;
  var hashMap := new Dictionary<integer, List<integer>>;

  for var i := 0 to sizeRow - 1 do
    for var j := 0 to sizeCol - 1 do
    begin
      if not hashMap.ContainsKey(i + j) then
        hashMap.Add(i + j, new List<integer>);
      hashMap[i + j].Add(mat[i][j]);
    end;

  for var val := 0 to sizeRow + sizeCol - 2 do
    if val mod 2 = 0 then
      res.AddRange(IEnumerable&<integer>(hashMap[val]).Reverse)
    else
      res.AddRange(hashMap[val]);

  Result := res;
end;

function MaxSightseeingScore(values: List<integer>): integer;
begin
  var arr1 := new List<integer>;
  var arr2 := new List<integer>;

  arr1.Add(values[0]);

  for var index := 1 to values.Count - 1 do
  begin
    arr1.Add(values[index] + index);
    arr2.Add(values[index] - index);
  end;

  arr1.RemoveAt(arr1.Count - 1);

  for var index := values.Count - 3 downto 0 do
    arr2[index] := Max(arr2[index], arr2[index + 1]);

  var maxim := integer.MinValue;
  for var index := 0 to values.Count - 2 do
    maxim := Max(maxim, arr1[index] + arr2[index]);

  Result := maxim;
end;

