function CircularSubarraySum(arr: List<integer>): integer;
begin
  var maxKadane := Kadane(arr);
  var maxWrap := 0;

  for var i := 0 to arr.Count - 1 do
  begin
    maxWrap := maxWrap + arr[i];
    arr[i] := -arr[i];
  end;

  maxWrap := maxWrap + Kadane(arr);

  if (maxWrap > maxKadane) and (maxWrap <> 0) then
    Result := maxWrap
  else
    Result := maxKadane;
end;

