function Search(row: List<integer>; edge: integer): integer;
begin
  var n := row.Count;
  if edge = n then
    Result := edge
  else
  begin
    var l := edge;
    var r := n - 1;
    while l <= r do
    begin
      var m := l + (r - l) div 2;
      if row[m] >= 0 then
        l := m + 1
      else
        r := m - 1;
    end;
    Result := l;
  end;
end;

