function IsPrimeNumber(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

function FindFirstKMissingPrimes(nums: List<integer>; k: integer): List<integer>;
begin
  var i := 2;
  var primeCount := 0;
  var missingPrimes := new List<integer>;

  while primeCount < k do
  begin
    if (not nums.Contains(i)) and IsPrimeNumber(i) then
    begin
      missingPrimes.Add(i);
      primeCount := primeCount + 1;
    end;
    i := i + 1;
  end;

  Result := missingPrimes;
end;

