function GetChar(strr: string): char;
begin
  var summ := 0;
  for var i := 0 to strr.Length - 1 do
    summ := summ + (integer(strr[i]) - integer('a') + 1);

  if summ mod 26 = 0 then
    Result := 'z'
  else
  begin
    summ := summ mod 26;
    Result := char(integer('a') + summ - 1);
  end;
end;

function ProductSumTuple(lst: List<integer>): List<(integer, integer)>;
begin
