  for var i := 0 to lst.Count - 2 do
    res.Add((lst[i] * lst[i + 1], lst[i] + lst[i + 1]));
  Result := res;
end;

function TranslateNumber(num: integer): integer;
begin
  var numStr := num.ToString;
  var dp := new integer[numStr.Length + 1];
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to numStr.Length do
  begin
    if StrToInt(numStr[i - 1].ToString) > 0 then
      dp[i] := dp[i - 1];

    var twoDigit := StrToInt(numStr.Substring(i - 2, 2));
    if (10 <= twoDigit) and (twoDigit <= 25) then
      dp[i] := dp[i] + dp[i - 2];
  end;

  Result := dp[numStr.Length];
end;

function FindClosest(nums: List<integer>; target: integer): integer;
begin
  if nums.Count = 0 then
    Result := 0
  else
  begin
    var start := 0;
    var endVal := nums.Count - 1;

    while start + 1 < endVal do
    begin
      var mid := (start + endVal) div 2;
      if nums[mid] = target then
      begin
        Result := nums[mid];
        exit;
      end
      else if nums[mid] < target then
        start := mid
      else
        endVal := mid;
    end;

    if Abs(nums[start] - target) <= Abs(nums[endVal] - target) then
      Result := nums[start]
    else
      Result := nums[endVal];
  end;
end;

function SecondSmallest(numbers: List<integer>): integer;
