  for var i := 0 to words.Count - 1 do
  begin
    if i = 0 then
    begin
      wordList.Add(words[i]);
      continue;
    end;

    if (words[i - 1][words[i - 1].Length - 1] <> words[i][0]) or (wordList.Contains(words[i])) then
    begin
      Result := False;
      exit;
    end
    else
      wordList.Add(words[i]);
  end;

  Result := True;
end;

