function NextLargest(n: integer): integer;
begin
  var digits := n.ToString.ToCharArray.ToList;
  var length := digits.Count;
  var i := length - 2;

  while i >= 0 do
  begin
    if digits[i] < digits[i + 1] then
      break;
    i := i - 1;
  end;

  if i < 0 then
    Result := -1
  else
  begin
    var j := length - 1;
    while j > i do
    begin
      if digits[j] > digits[i] then
        break;
      j := j - 1;
    end;

    var temp := digits[i];
    digits[i] := digits[j];
    digits[j] := temp;

    var sortedPart := digits.GetRange(i + 1, length - i - 1);
    sortedPart.Sort;
    var resultStr := string.Join('', digits.GetRange(0, i + 1)) + string.Join('', sortedPart);
    Result := StrToInt(resultStr);
  end;
end;

function IsPrime(num: integer): boolean;
begin
  if num < 2 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(num)) do
      if num mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

