function FibSumEven(n: integer): integer;
begin
  var a := 1;
  var b := 2;
  var total := 0;

  while b <= n do
  begin
    if b mod 2 = 0 then
      total := total + b;
    var temp := a;
    a := b;
    b := temp + b;
  end;

  Result := total;
end;

function DFS(graph: Dictionary<integer, List<integer>>; node, parent: integer; var visited: array of boolean): boolean;
begin
  visited[node] := True;

  if graph.ContainsKey(node) then
    foreach var neighbor in graph[node] do
    begin
      if not visited[neighbor] then
      begin
        if not DFS(graph, neighbor, node, visited) then
        begin
          Result := False;
          exit;
        end;
      end
      else if neighbor <> parent then
      begin
        Result := False;
        exit;
      end;
    end;

  Result := True;
end;

function CheckValidTree(n: integer; edges: List<List<integer>>): boolean;
begin
  if (n <= 0) or (edges.Count <> n - 1) then
    Result := False
  else
  begin
    var graph := new Dictionary<integer, List<integer>>;

    foreach var edge in edges do
    begin
      var u := edge[0];
      var v := edge[1];

      if not graph.ContainsKey(u) then
        graph.Add(u, new List<integer>);
      if not graph.ContainsKey(v) then
        graph.Add(v, new List<integer>);

      graph[u].Add(v);
      graph[v].Add(u);
    end;

    var visited := ArrFill(n, False);

    if not DFS(graph, 0, -1, visited) then
      Result := False
    else
    begin
      foreach var v in visited do
        if not v then
        begin
          Result := False;
          exit;
        end;
      Result := True;
    end;
  end;
end;

function MinimumPlatforms(arrivals, departures: List<integer>): integer;
begin
  arrivals.Sort;
  departures.Sort;
  var i := 1;
  var j := 0;
  var plat := 1;
  var maxVal := 1;

  while (i < arrivals.Count) and (j < departures.Count) do
  begin
    if arrivals[i] <= departures[j] then
    begin
      plat := plat + 1;
      i := i + 1;
    end
    else
    begin
      plat := plat - 1;
      j := j + 1;
    end;

    if plat > maxVal then
      maxVal := plat;
  end;

  Result := maxVal;
end;

function GroupAna(strs: List<string>): List<List<string>>;
