  foreach var strVal in strs do
  begin
    var count := new integer[26];
    foreach var c in strVal do
      count[integer(c) - integer('a')] := count[integer(c) - integer('a')] + 1;

    var key := string.Join(',', count);

    if res.ContainsKey(key) then
      res[key].Add(strVal)
    else
    begin
      res.Add(key, new List<string>);
      res[key].Add(strVal);
    end;
  end;

  Result := res.Values.ToList;
end;

function FrequentChars(s: string): List<char>;
begin
  var counter := new Dictionary<char, integer>;

  foreach var char in s do
    if counter.ContainsKey(char) then
      counter[char] := counter[char] + 1
    else
      counter.Add(char, 1);

  var maxFreq := counter.Values.Max;
  var res := new List<char>;

  foreach var char in s do
    if (counter[char] = maxFreq) and (not res.Contains(char)) then
      res.Add(char);

  Result := res;
end;

