function LongestArithSeq(nums: List<integer>): integer;
begin
  var arr := new Dictionary<(integer, integer), integer>;
  var n := nums.Count;
  var maxLength := 0;

  for var i := 0 to n - 1 do
    for var j := i + 1 to n - 1 do
    begin
      var diff := nums[j] - nums[i];
      var key := (j, diff);

      if arr.ContainsKey((i, diff)) then
        arr[key] := arr[(i, diff)] + 1
      else
        arr[key] := 2;

      maxLength := Max(maxLength, arr[key]);
    end;

  Result := maxLength;
end;

