function SmallestRepeatingSubstringIndex(s: string): integer;
begin
  var n := s.Length;
  for var i := 1 to n div 2 do
  begin
    if n mod i = 0 then
    begin
      var pattern := s.Substring(0, i);
      var repeated := '';
      for var j := 1 to n div i do
        repeated := repeated + pattern;

      if repeated = s then
      begin
        Result := i;
