function FindMin(nums: List<integer>): integer;
begin
  var l := 0;
  var r := nums.Count - 1;

  while l < r do
  begin
    var mid := (l + r) div 2;
    if nums[mid] > nums[r] then
      l := mid + 1
    else if nums[mid] < nums[r] then
      r := mid
    else
      r := r - 1;
  end;

  Result := nums[l];
end;

function CheckStraightLine(coordinates: List<List<integer>>): boolean;
begin
  if coordinates.Count <= 2 then
    Result := True
  else
  begin
    var (x0, y0) := (coordinates[0][0], coordinates[0][1]);
    var (x1, y1) := (coordinates[1][0], coordinates[1][1]);

    for var i := 2 to coordinates.Count - 1 do
    begin
      var (x, y) := (coordinates[i][0], coordinates[i][1]);
      if (x0 - x1) * (y1 - y) <> (x1 - x) * (y0 - y1) then
      begin
        Result := False;
        exit;
      end;
    end;
    Result := True;
  end;
end;

function GenerateSwaps(s: string): List<string>;
begin
  if s.Length <= 1 then
  begin
    Result := new List<string>;
    exit;
  end;

  var swappedStrings := new List<string>;
  for var i := 0 to s.Length - 2 do
  begin
    var swapped := s.ToCharArray;
    var temp := swapped[i];
    swapped[i] := swapped[i + 1];
    swapped[i + 1] := temp;
    swappedStrings.Add(string.Join('', swapped));
  end;

  Result := swappedStrings.Distinct.ToList;
end;

function LongestPalindromicSubsequence(strVal: string): integer;
begin
  var n := strVal.Length;
  var dp := new integer[n, n];

  for var i := n - 1 downto 0 do
  begin
    dp[i, i] := 1;
    for var j := i + 1 to n - 1 do
    begin
      if strVal[i] = strVal[j] then
        dp[i, j] := dp[i + 1, j - 1] + 2
      else
        dp[i, j] := Max(dp[i + 1, j], dp[i, j - 1]);
    end;
  end;
  Result := dp[0, n - 1];
end;

function MinStepsPalindrome(s: string): integer;
begin
  var lps := LongestPalindromicSubsequence(s);
  Result := s.Length - lps;
