function CanMakeChange(targetAmount: integer; denominations: List<integer>): boolean;
begin
  var dp := ArrFill(targetAmount + 1, False);
  dp[0] := True;

  for var amount := 1 to targetAmount do
    foreach var coin in denominations do
      if (coin <= amount) and dp[amount - coin] then
      begin
        dp[amount] := True;
        break;
      end;

  Result := dp[targetAmount];
end;

function MaxStockProfit(prices: List<integer>): integer;
begin
  if prices.Count = 0 then
    Result := 0
  else
  begin
    var minPrice := integer.MaxValue;
    var maxProfit := 0;

    foreach var price in prices do
    begin
      minPrice := Min(minPrice, price);
      var profit := price - minPrice;
      maxProfit := Max(maxProfit, profit);
    end;

    Result := maxProfit;
  end;
end;

