function NumBST(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    var num := 0;
    for var i := 1 to n do
    begin
      var numLeftSubtrees := NumBST(i - 1);
      var numRightSubtrees := NumBST(n - i);
      num := num + numLeftSubtrees * numRightSubtrees;
    end;
    Result := num;
  end;
end;

