    if anagramGroups.ContainsKey(sortedWord) then
      anagramGroups[sortedWord].Add(word)
    else
    begin
      anagramGroups.Add(sortedWord, new List<string>);
      anagramGroups[sortedWord].Add(word);
    end;
  end;

  var count := 0;
  foreach var group in anagramGroups.Values do
    if group.Count > 1 then
      count := count + 1;

  Result := count;
end;

