function SubarraysWithSumK(arr: List<integer>; k: integer): integer;
begin
  var count := 0;
  var currentSum := 0;
  var prefixSums := new Dictionary<integer, integer>;
  prefixSums.Add(0, 1);

  foreach var num in arr do
  begin
    currentSum := currentSum + num;
    if prefixSums.ContainsKey(currentSum - k) then
      count := count + prefixSums[currentSum - k];

    if prefixSums.ContainsKey(currentSum) then
      prefixSums[currentSum] := prefixSums[currentSum] + 1
    else
      prefixSums.Add(currentSum, 1);
  end;

  Result := count;
end;

function FindSmallestNonrepeated(arr: List<integer>): integer;
begin
  var hashTable := new Dictionary<integer, integer>;

  foreach var num in arr do
    if hashTable.ContainsKey(num) then
      hashTable[num] := hashTable[num] + 1
    else
      hashTable.Add(num, 1);

  var smallest := integer.MaxValue;
  foreach var num in arr do
    if (hashTable[num] = 1) and (num < smallest) then
      smallest := num;

  if smallest = integer.MaxValue then
    Result := -1
  else
    Result := smallest;
end;

