function CountUniqueBST(n: integer): integer;
begin
  if n = 0 then
    Result := 1
  else
  begin
    var dp := new integer[n + 1];
    dp[0] := 1;
    dp[1] := 1;
    for var i := 2 to n do
      for var j := 0 to i - 1 do
        dp[i] := dp[i] + dp[j] * dp[i - j - 1];
    Result := dp[n];
  end;
end;

function IsValidLicensePlate(licensePlate: string): boolean;
begin
  if (licensePlate.Length < 2) or (licensePlate.Length > 6) then
    Result := False
  else if not (licensePlate[0].IsLetter and licensePlate[1].IsLetter) then
    Result := False
  else if licensePlate.Any(ch -> not char.IsLetterOrDigit(ch)) then
    Result := False
  else
  begin
    var hasNumbers := false;
    for var i := 2 to licensePlate.Length - 1 do
    begin
      if licensePlate[i].IsDigit then
      begin
        hasNumbers := true;
        if (i = 2) and (licensePlate[i] = '0') then
        begin
          Result := False;
          exit;
        end;
      end;
    end;

    if hasNumbers and licensePlate[licensePlate.Length - 1].IsLetter then
      Result := False
    else
      Result := True;
  end;
end;

function FindLongestBitonicSubsequence(arr: List<integer>): integer;
begin
  var n := arr.Count;
  var inc := new integer[n];
  var dec := new integer[n];

  for var i := 0 to n - 1 do
  begin
    inc[i] := 1;
    dec[i] := 1;
  end;

  for var i := 1 to n - 1 do
    for var j := 0 to i - 1 do
      if (arr[i] > arr[j]) and (inc[i] < inc[j] + 1) then
        inc[i] := inc[j] + 1;

  for var i := n - 2 downto 0 do
    for var j := n - 1 downto i + 1 do
      if (arr[i] > arr[j]) and (dec[i] < dec[j] + 1) then
        dec[i] := dec[j] + 1;

  var maxLength := 0;
  for var i := 0 to n - 1 do
    maxLength := Max(maxLength, inc[i] + dec[i] - 1);

  Result := maxLength;
end;

