procedure GeneratePermutations(current: List<integer>; remaining: List<integer>; var res: List<List<integer>>);
begin
  if remaining.Count = 0 then
  begin
    if not res.Any(lst -> lst.SequenceEqual(current)) then
      res.Add(new List<integer>(current));
    exit;
  end;

  for var i := 0 to remaining.Count - 1 do
  begin
    var newCurrent := new List<integer>(current);
    newCurrent.Add(remaining[i]);
    var newRemaining := new List<integer>(remaining);
    newRemaining.RemoveAt(i);
    GeneratePermutations(newCurrent, newRemaining, res);
  end;
end;

function FindUniquePermutations(nums: List<integer>): List<List<integer>>;
begin
  var res := new List<List<integer>>;
  GeneratePermutations(new List<integer>, nums, res);
  Result := res;
end;

function LCS(X, Y: string): integer;
begin
  var m := X.Length;
  var n := Y.Length;
  var L := new integer[m + 1, n + 1];

  for var i := 0 to m do
  begin
    for var j := 0 to n do
    begin
      if (i = 0) or (j = 0) then
        L[i, j] := 0
      else if X[i - 1] = Y[j - 1] then
        L[i, j] := L[i - 1, j - 1] + 1
      else
        L[i, j] := Max(L[i - 1, j], L[i, j - 1]);
    end;
  end;

  Result := L[m, n];
end;

function RepeatedElement(A: List<integer>): integer;
begin
