end;

function FindLargestContinuousSum(arr: List<integer>): integer;
begin
  if arr.Count = 0 then
    Result := 0
  else
  begin
    var maxSoFar := arr[0];
    var maxEndingHere := arr[0];

    for var i := 1 to arr.Count - 1 do
    begin
      maxEndingHere := Max(arr[i], maxEndingHere + arr[i]);
      maxSoFar := Max(maxSoFar, maxEndingHere);
    end;

    Result := maxSoFar;
  end;
end;

function LongestEqualSubsequence(arr: List<integer>): integer;
