    for var i := 1 to arr.Count - 1 do
    begin
      if arr[i] = arr[i - 1] then
      begin
        currentLength := currentLength + 1;
        maxLength := Max(maxLength, currentLength);
      end
      else
        currentLength := 1;
    end;

    Result := maxLength;
  end;
end;

function FindTwoNumbers(nums: List<integer>; target: integer): List<integer>;
begin
  var numDict := new Dictionary<integer, integer>;
  for var i := 0 to nums.Count - 1 do
  begin
    var complement := target - nums[i];
    if numDict.ContainsKey(complement) then
    begin
      Result := new List<integer>;
      Result.Add(numDict[complement]);
      Result.Add(i);
      exit;
    end;
    numDict[nums[i]] := i;
  end;
  Result := new List<integer>;
end;

function FindLargestTime(arr: List<integer>): string;
begin
  var maxVal := -1;
  var ans := '';

  for var i := 0 to arr.Count - 1 do
    for var j := 0 to arr.Count - 1 do
      for var k := 0 to arr.Count - 1 do
        for var l := 0 to arr.Count - 1 do
        begin
          if (i = j) or (i = k) or (i = l) or (j = k) or (j = l) or (k = l) then
            continue;

          var hour := arr[i] * 10 + arr[j];
          var minute := arr[k] * 10 + arr[l];

          if (hour >= 0) and (hour <= 23) and (minute >= 0) and (minute <= 59) then
          begin
            var time := hour * 60 + minute;
            if time > maxVal then
            begin
              maxVal := time;
              ans := hour.ToString.PadLeft(2, '0') + ':' + minute.ToString.PadLeft(2, '0');
            end;
          end;
        end;

  Result := ans;
end;

