function CheckBrackets(s: string): boolean;
begin
  var stack := new Stack<char>;
  var mapping := new Dictionary<char, char>;
  mapping.Add(')', '(');
  mapping.Add('}', '{');
  mapping.Add(']', '[');

  foreach var char in s do
  begin
    if mapping.ContainsValue(char) then
      stack.Push(char)
    else if mapping.ContainsKey(char) then
    begin
      if (stack.Count = 0) or (stack.Peek() <> mapping[char]) then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;

