    for var i := 0 to shortest.Length - 1 do
    begin
      var currentChar := shortest[i];
      foreach var other in strs do
        if other[i] <> currentChar then
        begin
          Result := shortest.Substring(0, i);
          exit;
        end;
    end;

    Result := shortest;
  end;
end;

function RemoveKDigits(num: string; k: integer): string;
