  foreach var n in num do
  begin
    while (res.Count > 0) and (k > 0) and (res[res.Count - 1] > n) do
    begin
      res.RemoveAt(res.Count - 1);
      k := k - 1;
    end;
    res.Add(n);
  end;

  while k > 0 do
  begin
    res.RemoveAt(res.Count - 1);
    k := k - 1;
  end;

  var resultStr := string.Join('', res).TrimStart('0');
  if resultStr = '' then
    Result := '0'
  else
    Result := resultStr;
end;

