function DistSq(point1, point2: (integer, integer)): integer;
begin
  Result := (point1.Item1 - point2.Item1) * (point1.Item1 - point2.Item1) + 
            (point1.Item2 - point2.Item2) * (point1.Item2 - point2.Item2);
end;

function ValidRectangle(p1, p2, p3, p4: (integer, integer)): boolean;
