function MinDeleteAnagram(str1, str2: string): integer;
begin
  var c1 := new Dictionary<char, integer>;
  var c2 := new Dictionary<char, integer>;

  foreach var ch in str1 do
    if c1.ContainsKey(ch) then
      c1[ch] := c1[ch] + 1
    else
      c1.Add(ch, 1);

  foreach var ch in str2 do
    if c2.ContainsKey(ch) then
      c2[ch] := c2[ch] + 1
    else
      c2.Add(ch, 1);

  var common := 0;
  foreach var pair in c1 do
    if c2.ContainsKey(pair.Key) then
      common := common + Min(pair.Value, c2[pair.Key]);

  Result := (str1.Length - common) + (str2.Length - common);
end;

procedure DFS(matrix: List<List<integer>>; i, j: integer; var path: StringBuilder; direction: char);
begin
  if (i < 0) or (i >= matrix.Count) or (j < 0) or (j >= matrix[0].Count) or (matrix[i][j] <> 1) then
    exit;

  matrix[i][j] := 0;
  path.Append(direction);

  DFS(matrix, i + 1, j, path, 'D');
  DFS(matrix, i - 1, j, path, 'U');
  DFS(matrix, i, j + 1, path, 'R');
  DFS(matrix, i, j - 1, path, 'L');

  path.Append('B');
end;

function CountDistinctIslands(matrix: List<List<integer>>): integer;
begin
  if matrix.Count = 0 then
  begin
    Result := 0;
    exit;
  end;

  var distinctIslands := new HashSet<string>;

  for var i := 0 to matrix.Count - 1 do
    for var j := 0 to matrix[0].Count - 1 do
      if matrix[i][j] = 1 then
      begin
        var path := new StringBuilder;
        DFS(matrix, i, j, path, 'O');
        distinctIslands.Add(path.ToString);
      end;

  Result := distinctIslands.Count;
end;

function FastPower(x: real; n: integer): real;
begin
  if n = 0 then
    Result := 1
  else if n < 0 then
    Result := 1 / FastPower(x, -n)
  else if n mod 2 = 0 then
  begin
    var halfPower := FastPower(x, n div 2);
    Result := halfPower * halfPower;
  end
  else
    Result := x * FastPower(x, n - 1);
end;

function ReverseListInPlace(nums: List<integer>): List<integer>;
begin
  var left := 0;
  var right := nums.Count - 1;

  while left < right do
  begin
    var temp := nums[left];
    nums[left] := nums[right];
    nums[right] := temp;

    left := left + 1;
    right := right - 1;
  end;

  Result := nums;
end;

function NumOccurrences(strVal, substring: string): integer;
