  foreach var char in s do
  begin
    if char = '(' then
      stack.Push(char)
    else if char = ')' then
    begin
      if stack.Count = 0 then
      begin
        Result := False;
        exit;
      end;
      stack.Pop;
    end;
  end;

  Result := stack.Count = 0;
end;

