function MaxUniqueCharacters(s: string): integer;
begin
  var charIndex := new Dictionary<char, integer>;
  var maxLength := 0;
  var start := 0;

  for var endIndex := 0 to s.Length - 1 do
  begin
    if charIndex.ContainsKey(s[endIndex]) and (charIndex[s[endIndex]] >= start) then
      start := charIndex[s[endIndex]] + 1;

    charIndex[s[endIndex]] := endIndex;
    maxLength := Max(maxLength, endIndex - start + 1);
  end;

  Result := maxLength;
end;

function SortedListIntersection(list1, list2: List<integer>): List<integer>;
begin
  var intersection := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < list1.Count) and (j < list2.Count) do
  begin
    if list1[i] < list2[j] then
      i := i + 1
    else if list1[i] > list2[j] then
      j := j + 1
    else
    begin
      intersection.Add(list1[i]);
      i := i + 1;
      j := j + 1;
    end;
  end;

  Result := intersection;
end;

function ToLowerCase(strList: List<string>): List<string>;
