    foreach var ch in word do
    begin
      if (ch >= 'A') and (ch <= 'Z') then
        temp.Add(chr(ord(ch) + 32))
      else
        temp.Add(ch);
    end;
    res.Add(string.Join('', temp));
  end;

  Result := res;
end;

function IsPalindromeIgnoringSpecial(s: string): boolean;
begin
  var filteredChars := new List<char>;

  foreach var ch in s do
    if char.IsLetterOrDigit(ch) then
      filteredChars.Add(ch.ToLower);

  var left := 0;
  var right := filteredChars.Count - 1;

  while left < right do
  begin
    if filteredChars[left] <> filteredChars[right] then
    begin
      Result := False;
      exit;
    end;
    left := left + 1;
    right := right - 1;
  end;

  Result := True;
end;

function UniqueBST(n: integer): integer;
begin
  if n <= 1 then
    Result := 1
  else
  begin
    var dp := new integer[n + 1];
    dp[0] := 1;
    dp[1] := 1;

    for var i := 2 to n do
      for var j := 1 to i do
        dp[i] := dp[i] + dp[j - 1] * dp[i - j];

    Result := dp[n];
  end;
end;

function MinBitFlips(a, b, c: integer): integer;
begin
  var flips := 0;

  for var i := 0 to 31 do
  begin
    var bitA := (a shr i) and 1;
    var bitB := (b shr i) and 1;
    var bitC := (c shr i) and 1;

    if bitC = 0 then
      flips := flips + bitA + bitB
    else
      if (bitA + bitB) = 0 then
        flips := flips + 1;
  end;

  Result := flips;
end;

function FindMinArrowShots(points: List<List<integer>>): integer;
begin
  if points.Count = 0 then
  begin
    Result := 0;
    exit;
  end;

  points.Sort((x, y) -> x[1].CompareTo(y[1]));
  var arrows := 1;
  var endVal := points[0][1];

  for var i := 1 to points.Count - 1 do
  begin
    if points[i][0] > endVal then
    begin
      arrows := arrows + 1;
      endVal := points[i][1];
    end;
  end;

  Result := arrows;
end;

