function FindLongestCommonSubstring(str1, str2: string): string;
begin
  var m := str1.Length;
  var n := str2.Length;
  var dp := new integer[m + 1, n + 1];
  var maxLen := 0;
  var endIndex := 0;

  for var i := 1 to m do
  begin
    for var j := 1 to n do
    begin
      if str1[i - 1] = str2[j - 1] then
      begin
        dp[i, j] := dp[i - 1, j - 1] + 1;
        if dp[i, j] > maxLen then
        begin
          maxLen := dp[i, j];
          endIndex := i;
        end;
      end
      else
        dp[i, j] := 0;
    end;
  end;

  if maxLen = 0 then
    Result := ''
  else
    Result := str1.Substring(endIndex - maxLen, maxLen);
end;

