function ZigzagPattern(s: string; numRows: integer): string;
begin
  if numRows = 1 then
  begin
    Result := s;
    exit;
  end;

  var ans := '';
  var interval := 2 * (numRows - 1);

  for var i := 0 to s.Length - 1 step interval do
    ans := ans + s[i];

  for var row := 1 to numRows - 2 do
  begin
    var inter := 2 * row;
    var i := row;
    while i < s.Length do
    begin
      ans := ans + s[i];
      inter := interval - inter;
      i := i + inter;
    end;
  end;

  for var i := numRows - 1 to s.Length - 1 step interval do
    ans := ans + s[i];

  Result := ans;
end;

function LongestRepeatingCharacterReplacement(s: string; k: integer): integer;
begin
  var char2count := new Dictionary<char, integer>;
  var maxLen := 0;
  var start := 0;

  for var endIndex := 0 to s.Length - 1 do
  begin
    if char2count.ContainsKey(s[endIndex]) then
      char2count[s[endIndex]] := char2count[s[endIndex]] + 1
    else
      char2count.Add(s[endIndex], 1);

    while (endIndex - start + 1 - char2count.Values.Max) > k do
    begin
      char2count[s[start]] := char2count[s[start]] - 1;
      start := start + 1;
    end;

    maxLen := Max(maxLen, endIndex - start + 1);
  end;

  Result := maxLen;
end;

procedure CountWays(numbers: List<integer>; i: integer; var counts: List<List<integer>>);
begin
  var n := numbers.Count;
  var plus := numbers.GetRange(0, n - i);
  if i = 1 then
  begin
    foreach var count in counts.ToList do
    begin
      var newCount := new List<integer>(plus);
      newCount.Add(-1 * numbers[n - i]);
      counts.Add(newCount);
    end;
  end
  else
  begin
    foreach var count in counts.ToList do
    begin
      var newCount := new List<integer>(plus);
      newCount.Add(-1 * numbers[n - i]);
      newCount.AddRange(count.GetRange(n - i + 1, count.Count - (n - i + 1)));
      counts.Add(newCount);
    end;
  end;
end;

function CountTargetSums(numbers: List<integer>; target: integer): integer;
begin
  var answer := 0;
  var n := numbers.Count;
  var counts := new List<List<integer>>;
  counts.Add(numbers);

  for var i := 1 to n do
    CountWays(numbers, i, counts);

  var results := counts.Select(lst -> lst.Sum).ToList;
  answer := results.Count(val -> val = target);

  Result := answer;
end;

function ConvertTemperature(source: string; temp: real): real;
begin
  if source = 'C' then
    Result := (temp * 9 / 5) + 32
  else if source = 'F' then
    Result := (temp - 32) * 5 / 9
  else
    raise new System.ArgumentException('Invalid source. Please use ''C'' for Celsius or ''F'' for Fahrenheit.');
end;

function IsPrimeNumber(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else if n <= 3 then
    Result := True
  else if (n mod 2 = 0) or (n mod 3 = 0) then
    Result := False
  else
  begin
    var i := 5;
    while i * i <= n do
    begin
      if (n mod i = 0) or (n mod (i + 2) = 0) then
      begin
        Result := False;
        exit;
      end;
      i := i + 6;
    end;
    Result := True;
  end;
end;

function SumOfDigits(n: integer): integer;
begin
  var sumVal := 0;
  var numStr := n.ToString;
  foreach var digitChar in numStr do
    sumVal := sumVal + StrToInt(digitChar.ToString);
  Result := sumVal;
end;

function KthPrimeSumNumber(k: integer): integer;
begin
  var count := 0;
  var num := 1;

  while True do
  begin
    if IsPrimeNumber(SumOfDigits(num)) then
    begin
      count := count + 1;
      if count = k then
      begin
        Result := num;
        exit;
      end;
    end;
    num := num + 1;
  end;
end;

function LetterCounts(s: string): Dictionary<char, integer>;
begin
  var filteredChars := new List<char>;

  foreach var char in s do
    if char.IsLetter then
      filteredChars.Add(char.ToLower);

  var counts := new Dictionary<char, integer>;

  foreach var char in filteredChars do
    if counts.ContainsKey(char) then
      counts[char] := counts[char] + 1
    else
      counts.Add(char, 1);

  Result := counts;
end;

function SearchFun(arr: List<integer>; left, right: integer): integer;
begin
  var mid := (left + right) div 2;

  if left > right then
  begin
    Result := -1;
    exit;
  end;

  if (arr[mid] > arr[mid - 1]) and (arr[mid] > arr[mid + 1]) then
    Result := mid
  else
  begin
    if (mid < arr.Count - 1) and (arr[mid] < arr[mid + 1]) then
      Result := SearchFun(arr, mid + 1, right)
    else if (mid < arr.Count - 1) and (arr[mid] > arr[mid + 1]) then
      Result := SearchFun(arr, left, mid - 1)
    else
      Result := -1;
  end;
end;

function PeakIndexInMountainArray(arr: List<integer>): integer;
begin
  if arr.Count = 0 then
  begin
    Result := -1;
    exit;
  end;

  if arr.Count = 1 then
  begin
    Result := 0;
    exit;
  end;

  Result := SearchFun(arr, 0, arr.Count - 1);
end;

type
  TreeNode = class
  public
    children: Dictionary<char, TreeNode>;

    constructor;
    begin
      children := new Dictionary<char, TreeNode>;
    end;
  end;

function MinimumLengthEncoding(words: List<string>): integer;
begin
  var root := new TreeNode;
  var leaves := new List<(TreeNode, integer)>;

  // Build tree with words in reverse order
  foreach var word in words do
  begin
    var node := root;
    for var i := word.Length - 1 downto 0 do
    begin
      var c := word[i];
      if not node.children.ContainsKey(c) then
        node.children.Add(c, new TreeNode);
      node := node.children[c];
    end;
    leaves.Add((node, word.Length + 1)); // +1 for '#'
  end;

  // Count only leaf nodes (nodes with no children)
  var res := 0;
  foreach var leaf in leaves do
    if leaf[0].children.Count = 0 then
      res := res + leaf[1];

  Result := res;
end;

function Partition(nums: List<integer>; low, high: integer): integer;
begin
  var pivot := nums[high];
  var i := low - 1;

  for var j := low to high - 1 do
  begin
    if nums[j] <= pivot then
    begin
      i := i + 1;
      var temp := nums[i];
      nums[i] := nums[j];
      nums[j] := temp;
    end;
  end;

  var temp := nums[i + 1];
  nums[i + 1] := nums[high];
  nums[high] := temp;

  Result := i + 1;
end;

function QuickSelect(nums: List<integer>; k, low, high: integer): integer;
begin
  if low = high then
  begin
    Result := nums[low];
    exit;
  end;

  var pivotIndex := Partition(nums, low, high);

  if k = pivotIndex then
    Result := nums[k]
  else if k < pivotIndex then
    Result := QuickSelect(nums, k, low, pivotIndex - 1)
  else
    Result := QuickSelect(nums, k, pivotIndex + 1, high);
end;

function KthSmallestElement(nums: List<integer>; k: integer): integer;
begin
  if (k < 1) or (k > nums.Count) then
    raise new System.ArgumentException('k is out of bounds!');

  Result := QuickSelect(nums, k - 1, 0, nums.Count - 1);
end;

function FlattenEven(nestedList: List<List<integer>>): List<integer>;
begin
  var res := new List<integer>;

  foreach var sublist in nestedList do
    foreach var num in sublist do
      if num mod 2 = 0 then
        res.Add(num);

  Result := res;
end;

type
  TreeNode = class
    val: integer;
    left: TreeNode;
    right: TreeNode;

    constructor(v: integer; l: TreeNode := nil; r: TreeNode := nil);
    begin
      val := v;
      left := l;
      right := r;
    end;
