function GetLeafValues(node: TreeNode): List<integer>;
begin
  if node = nil then
  begin
    Result := new List<integer>;
    exit;
  end;

  if (node.left = nil) and (node.right = nil) then
  begin
    Result := new List<integer>;
    Result.Add(node.val);
  end
  else
    Result := GetLeafValues(node.left).Concat(GetLeafValues(node.right)).ToList;
end;

function CompareLeafNodes(root1, root2: TreeNode): boolean;
begin
  var leaves1 := GetLeafValues(root1);
  var leaves2 := GetLeafValues(root2);

  Result := leaves1.SequenceEqual(leaves2);
end;

function LongestConsecutive(nums: List<integer>): integer;
begin
  if nums.Count = 0 then
  begin
    Result := 0;
    exit;
  end;

  var numSet := new HashSet<integer>(nums);
  var longestStreak := 0;

  foreach var num in numSet do
  begin
    if not numSet.Contains(num - 1) then
    begin
      var currentNum := num;
      var currentStreak := 1;

      while numSet.Contains(currentNum + 1) do
      begin
        currentNum := currentNum + 1;
        currentStreak := currentStreak + 1;
      end;

      longestStreak := Max(longestStreak, currentStreak);
    end;
  end;

  Result := longestStreak;
end;

function FibUpTo(limit: integer): List<integer>;
begin
  var fibList := new List<integer>;

  if limit >= 0 then
    fibList.Add(0);

  if limit >= 1 then
  begin
    fibList.Add(1);
    var a := 0;
    var b := 1;

    while True do
    begin
      var nextFib := a + b;
      if nextFib > limit then
        break;
      fibList.Add(nextFib);
      a := b;
      b := nextFib;
    end;
  end;

  Result := fibList;
end;

function KnightMoves(x1, y1, x2, y2: integer): integer;
begin
  var moves := new List<(integer, integer)>;
  moves.Add((2, 1));
  moves.Add((1, 2));
  moves.Add((-1, -2));
  moves.Add((-2, -1));
  moves.Add((-2, 1));
  moves.Add((-1, 2));
  moves.Add((1, -2));
  moves.Add((2, -1));

  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((x1, y1, 0));
  var visited := new HashSet<(integer, integer)>;
  visited.Add((x1, y1));

  while queue.Count > 0 do
  begin
    var (x, y, c) := queue.Dequeue;

    if (x = x2) and (y = y2) then
    begin
      Result := c;
      exit;
    end;

    foreach var (dx, dy) in moves do
    begin
      var nx := x + dx;
      var ny := y + dy;

      if (nx >= 0) and (nx < 8) and (ny >= 0) and (ny < 8) and (not visited.Contains((nx, ny))) then
      begin
        visited.Add((nx, ny));
        queue.Enqueue((nx, ny, c + 1));
      end;
    end;
  end;

  Result := -1;
end;

function FindFirstNonRepeated(s: string): char;
begin
  var charCount := new Dictionary<char, integer>;

  foreach var char in s do
    if charCount.ContainsKey(char) then
      charCount[char] := charCount[char] + 1
    else
      charCount.Add(char, 1);

  foreach var char in s do
    if charCount[char] = 1 then
    begin
      Result := char;
      exit;
    end;

  Result := #0;
end;

function UniqueSummands(n: integer): List<integer>;
begin
  var summands := new List<integer>;
  var current := 1;

  while n > 0 do
  begin
    if n <= 2 * current then
    begin
      summands.Add(n);
      break;
    end
    else
    begin
      summands.Add(current);
      n := n - current;
      current := current + 1;
    end;
  end;

  Result := summands;
end;

function MaxAreaHistogram(heights: List<integer>): integer;
begin
  var stack := new Stack<integer>;
  var maxArea := 0;
  var index := 0;

  while index < heights.Count do
  begin
    if (stack.Count = 0) or (heights[stack.Peek] <= heights[index]) then
    begin
      stack.Push(index);
      index := index + 1;
    end
    else
    begin
      var top := stack.Pop;
      var area := heights[top] * (if stack.Count = 0 then index else (index - stack.Peek - 1));
      maxArea := Max(maxArea, area);
    end;
  end;

  while stack.Count > 0 do
  begin
    var top := stack.Pop;
    var area := heights[top] * (if stack.Count = 0 then index else (index - stack.Peek - 1));
    maxArea := Max(maxArea, area);
  end;

  Result := maxArea;
end;

function FindSubArrays(arr: List<integer>; s: integer): integer;
begin
  var count := 0;
  var sumMap := new Dictionary<integer, integer>;
  var currSum := 0;

  for var i := 0 to arr.Count - 1 do
  begin
    currSum := currSum + arr[i];

    if currSum = s then
      count := count + 1;

    if sumMap.ContainsKey(currSum - s) then
      count := count + sumMap[currSum - s];

    if sumMap.ContainsKey(currSum) then
      sumMap[currSum] := sumMap[currSum] + 1
    else
      sumMap.Add(currSum, 1);
  end;

  Result := count;
end;

