function OptimalStockProfit(prices: List<integer>): integer;
begin
  var profit := 0;

  for var i := 1 to prices.Count - 1 do
    if prices[i] > prices[i - 1] then
      profit := profit + (prices[i] - prices[i - 1]);

  Result := profit;
end;

function RomanToInt(s: string): integer;
begin
  var romanValues := new Dictionary<char, integer>;
  romanValues.Add('I', 1);
  romanValues.Add('V', 5);
  romanValues.Add('X', 10);
  romanValues.Add('L', 50);
  romanValues.Add('C', 100);
  romanValues.Add('D', 500);
  romanValues.Add('M', 1000);

  var total := 0;
  var prevValue := 0;

  for var i := s.Length - 1 downto 0 do
  begin
    var value := romanValues[s[i]];
    if value < prevValue then
      total := total - value
    else
      total := total + value;
    prevValue := value;
  end;

  Result := total;
end;

function FindPositionInSortedArray(arr: List<integer>; target: integer): integer;
begin
  var low := 0;
  var high := arr.Count - 1;
  var resultIndex := -1;

  while low <= high do
  begin
    var mid := (low + high) div 2;

    if arr[mid] = target then
    begin
      resultIndex := mid;
      high := mid - 1;
    end
    else if arr[mid] > target then
      high := mid - 1
    else
      low := mid + 1;
  end;

  Result := resultIndex;
end;

