function CanFormTarget(target: string; wordset: List<string>): boolean;
begin
  if target = '' then
  begin
    Result := True;
    exit;
  end;

  foreach var word in wordset do
  begin
    if target.StartsWith(word) then
    begin
      var suffix := target.Substring(word.Length);
      if CanFormTarget(suffix, wordset) then
      begin
        Result := True;
        exit;
      end;
    end;
  end;

  Result := False;
end;

function SearchMatrix(matrix: List<List<integer>>; target: integer): boolean;
begin
  var m := matrix.Count;
  if m = 0 then
  begin
    Result := False;
    exit;
  end;

  var n := matrix[0].Count;
  var ans := False;

  for var i := 0 to m - 1 do
  begin
    var l := 0;
    var r := n - 1;

    if (target >= matrix[i][l]) and (target <= matrix[i][r]) then
    begin
      while l <= r do
      begin
        var mid := (l + r) div 2;
        if matrix[i][mid] = target then
        begin
          ans := True;
          break;
        end
        else if matrix[i][mid] < target then
          l := mid + 1
        else
          r := mid - 1;
      end;

      if ans then
        break;
    end;
  end;

  Result := ans;
end;

function SubArraySum(nums: List<integer>; k: integer): integer;
begin
  var d := new Dictionary<integer, integer>;
  d.Add(0, 1);
  var count := 0;
  var sumSoFar := 0;

  foreach var num in nums do
  begin
    sumSoFar := sumSoFar + num;
    var diff := sumSoFar - k;

    if d.ContainsKey(diff) then
      count := count + d[diff];

    if d.ContainsKey(sumSoFar) then
      d[sumSoFar] := d[sumSoFar] + 1
    else
      d.Add(sumSoFar, 1);
  end;

  Result := count;
end;

function SqrtNewtonRaphson(number: real; tolerance: real := 1e-10): real;
begin
  if number < 0 then
    raise new System.ArgumentException('Cannot compute square root of a negative number');

  if number = 0 then
  begin
    Result := 0;
    exit;
  end;

  var guess := number;

  while True do
  begin
    var betterGuess := (guess + number / guess) / 2.0;
    if Abs(guess - betterGuess) < tolerance then
    begin
      Result := betterGuess;
      exit;
    end;
    guess := betterGuess;
  end;
end;

