function IsPrime(n: integer): boolean;
begin
  if n <= 1 then
    Result := False
  else
  begin
    for var i := 2 to Round(Sqrt(n)) do
      if n mod i = 0 then
      begin
        Result := False;
        exit;
      end;
    Result := True;
  end;
end;

function NewmanPrime(n: integer): integer;
begin
  if (n = 0) or (n = 1) then
    Result := 1
  else
  begin
    var a := new List<integer>;
    a.Add(1);
    a.Add(1);

    for var i := 2 to n do
      a.Add(2 * a[i - 1] + a[i - 2]);

    for var i := n downto 0 do
      if IsPrime(a[i]) then
      begin
        Result := a[i];
        exit;
      end;

    Result := -1;
  end;
end;

function FindLeader(arr: List<integer>): List<integer>;
begin
  if arr.Count = 0 then
  begin
    Result := new List<integer>;
    exit;
  end;

  var maxRight := arr[arr.Count - 1];
  var resultList := new List<integer>;
  resultList.Add(maxRight);

  for var i := arr.Count - 2 downto 0 do
  begin
    if arr[i] > maxRight then
    begin
      resultList.Add(arr[i]);
      maxRight := arr[i];
    end;
  end;

  resultList.Reverse;
  Result := resultList;
end;

function StrToNum(strNum: string): integer;
begin
  var dig := new Dictionary<string, string>;
  dig.Add('zero', '0');
  dig.Add('one', '1');
  dig.Add('two', '2');
  dig.Add('three', '3');
  dig.Add('four', '4');
  dig.Add('five', '5');
  dig.Add('six', '6');
  dig.Add('seven', '7');
  dig.Add('eight', '8');
  dig.Add('nine', '9');

  var res := '';
  var words := strNum.Split(' ').ToList;

  foreach var word in words do
    res := res + dig[word];

  Result := StrToInt(res);
end;

function SumDigitsRecursively(num: integer): integer;
begin
  if num = 0 then
    Result := 0
  else
    Result := (num mod 10) + SumDigitsRecursively(num div 10);
end;

function StringSort(strings: List<string>): List<string>;
begin
